class Solution {
  public boolean checkPrimeFrequency(int[] nums) {
    int[] freq = new int[101];
    for (int x : nums) freq[x]++;
    for (int f : freq) {
      if (isPrime(f)) return true;
    }
    return false;
  }

  private boolean isPrime(int n) {
    if (n < 2) return false;
    for (int d = 2; d * d <= n; d++) {
      if (n % d == 0) return false;
    }
    return true;
  }
}
